#include <sqlite3.h>
#include <iostream>
#include <optional>
#include <string>
#include <unordered_map>
int main(){int id{};std::cin>>id;sqlite3* db=nullptr;sqlite3_open(":memory:",&db);sqlite3_exec(db,"CREATE TABLE records(id INTEGER PRIMARY KEY,value TEXT); INSERT INTO records VALUES(7,'cpp');",nullptr,nullptr,nullptr);std::unordered_map<int,std::optional<std::string>> cache;int queries=0;auto fetch=[&](int key){if(auto found=cache.find(key);found!=cache.end())return found->second;++queries;sqlite3_stmt* statement=nullptr;sqlite3_prepare_v2(db,"SELECT value FROM records WHERE id=?",-1,&statement,nullptr);sqlite3_bind_int(statement,1,key);std::optional<std::string> value;if(sqlite3_step(statement)==SQLITE_ROW)value=std::string(reinterpret_cast<const char*>(sqlite3_column_text(statement,0)));sqlite3_finalize(statement);cache[key]=value;return value;};fetch(id);const auto second=fetch(id);sqlite3_close(db);std::cout<<"value="<<(second?*second:"missing")<<" db_queries="<<queries<<"\n";}

